25	struct Config {
26	  std::string path;
27	};
28	
29	
30	bool ParseArgs(int argc, char **argv, Config &config) {
31	  for (int i = 1; i < argc; i++) {
32	    std::string arg = argv[i];
33	
34	    if (arg == "--path" && i + 1 < argc) {
35	      config.path = argv[++i];
36	    } else if (arg == "--help" || arg == "-h") {
37	      return false;
38	    }
39	  }
40	
41	  // Validate required arguments
42	  if (config.path.empty()) {
43	    return false;
44	  }
45	
46	  return true;
47	}
48	
49	
50	void PrintUsage(const char *program) {
51	  std::cout << "Usage: " << program << " --path <collection_path>" << std::endl;
52	  std::cout << std::endl;
53	  std::cout << "Arguments:" << std::endl;
54	  std::cout << "  --path         Path to the collection (required)"
55	            << std::endl;
56	}
57	
58	
59	int main(int argc, char **argv) {
60	  Config config;
61	
62	  // Parse arguments
63	  if (!ParseArgs(argc, argv, config)) {
64	    PrintUsage(argv[0]);
65	#ifdef __ANDROID__
66	    _exit(1);
67	#endif
68	    return 1;
69	  }
70	
71	  try {
72	    std::filesystem::path cwd = std::filesystem::current_path();
73	    std::cout << "[collection_optimizer] Current Working Directory: "
74	              << cwd.string() << std::endl;
75	  } catch (const std::filesystem::filesystem_error &e) {
76	    std::cout << "[collection_optimizer] Failed to get the current working "
77	                 "directory: "
78	              << e.what() << std::endl;
79	  }
80	
81	  std::cout << "Configuration:" << std::endl;
82	  std::cout << "  Path:        " << config.path << std::endl;
83	  std::cout << std::endl;
84	
85	  // Scope 'result' so its shared_ptr is released before we call _exit().
86	  zvec::Collection::Ptr collection;
87	  {
88	    auto result = zvec::Collection::Open(config.path,
89	                                         zvec::CollectionOptions{false, true});
90	    if (!result) {
91	      LOG_ERROR("Failed to open collection[%s]: %s", config.path.c_str(),
92	                result.error().c_str());
93	#ifdef __ANDROID__
94	      _exit(1);
95	#endif
96	      return -1;
97	    }
98	    collection = result.value();
99	  }
100	  std::cout << "Collection[" << config.path.c_str() << "] opened successfully"
101	            << std::endl;
102	
103	  // Print initial stats
104	  std::cout << "Initial stats: " << collection->Stats()->to_string_formatted()
105	            << std::endl;
106	
107	  auto s = collection->Optimize(zvec::OptimizeOptions{2});
108	  if (s.ok()) {
109	    std::cout << "Optimize completed successfully" << std::endl;
110	    // Print final stats
111	    std::cout << "Final stats: " << collection->Stats()->to_string_formatted()
112	              << std::endl;
113	#ifdef __ANDROID__
114	    // On Android with c++_static STL, static destructors of glog/gflags
115	    // crash during process teardown.  Use _exit() to skip them.
116	    collection->Flush();
117	    collection.reset();
118	    sync();
119	    std::cout.flush();
120	    std::cerr.flush();
121	    fflush(stdout);
122	    fflush(stderr);
123	    _exit(0);
124	#endif
125	    return 0;
126	  } else {
127	    std::cout << "Optimize failed: " << s.message() << std::endl;
128	#ifdef __ANDROID__
129	    collection.reset();
130	    sync();
131	    std::cout.flush();
132	    std::cerr.flush();
133	    fflush(stdout);
134	    fflush(stderr);
135	    _exit(1);
136	#endif
137	    return 1;
138	  }
