4303	Status SegmentImpl::open_wal_file() {
4304	  auto mem_block = segment_meta_->writing_forward_block().value();
4305	  std::string wal_file_path =
4306	      FileHelper::MakeWalPath(path_, segment_meta_->id(), mem_block.id_);
4307	  WalOptions wal_option;
4308	  if (std::filesystem::exists(wal_file_path)) {
4309	    wal_option.create_new = false;
4310	  } else {
4311	    wal_option.create_new = true;
4312	  }
4313	
4314	  if (WalFile::CreateAndOpen(wal_file_path, wal_option, &wal_file_) != 0) {
4315	    LOG_ERROR("WAL open failed: unable to create/open WAL file [%s]",
4316	              wal_file_path.c_str());
4317	    return Status::InternalError("Failed to open wal file: ", wal_file_path);
4318	  }
4319	
4320	  LOG_INFO("WAL opened [%s]: segment[%d]", wal_file_path.c_str(), id());
4321	  return Status::OK();
4322	}
