4324	Status SegmentImpl::append_wal(const Doc &doc) {
4325	  std::vector<uint8_t> buf = doc.serialize();
4326	
4327	  if (!wal_file_) {
4328	    auto s = open_wal_file();
4329	    CHECK_RETURN_STATUS(s);
4330	  }
4331	
4332	  auto ret = wal_file_->append(std::string(buf.begin(), buf.end()));
4333	  if (ret != 0) {
4334	    LOG_ERROR("WAL append failed: segment[%d], pk[%s], op[%d], ret[%d]", id(),
4335	              doc.pk().c_str(), static_cast<int>(doc.get_operator()), ret);
4336	    return Status::InternalError("Failed to append wal");
4337	  }
4338	
4339	  return Status::OK();
4340	}
